  for (unsigned int i = 0; i < divisions; i++) {
    xprimea = division_width * (1.0 * i);
    xprimem = division_width * (1.0 * i + 0.5);
    xprimeb = division_width * (1.0 * i + 1.0);
    xx[0] = x[0] - xprimea;
    xx[1] = x[0] - xprimem;
    xx[2] = x[0] - xprimeb;

