   "-"
   << second->getDomainLowerBound() + second->getDomainRange() << "
   "<<second->getDomainRange()<<std::endl;
   */

  val = val * division_width / 6.0;
  /*if(val != val)
   std::cout << "x = " << x[0] << " -> " << val << std::endl;*/
  // std::cout<<val<<std::endl;
  return val;
}

