  ASSERT_EQ(detector_info->MdtGeometry(), kTRUE);

  // Setup PndPidMdtInfo
  FairRuntimeDb *db = run->GetRuntimeDb();
  db->getContainer("PndPidCorrPar");
  db->initContainers(run->getRunId());

  detector_info->SetIdeal(kFALSE);
  detector_info->SetDetectorMode(2);
  detector_info->SetUsePropagator(kTRUE);
  PndGeanePro *propagator = new PndGeanePro();
  detector_info->SetPropagator(propagator);
  detector_info->ActivateDebugNtuple(kFALSE);
  detector_info->SetPidHypo(-11);
  detector_info->SetMdtRefit(kFALSE);
  detector_info->SetCorrPar((PndPidCorrPar *)db->getContainer("PndPidCorrPar"));

  // Create MDT hit far from track
  TVector3 vec(50, -50, 600);

  detector_info->SetMdtHit(10000000, vec, kTRUE);

  // Make sure that hit was created
  ASSERT_EQ(detector_info->GetMdtHit()->GetEntriesFast(), 1);

  // Set MdtMapping and reset MDT track
  detector_info->MdtMapping();
  detector_info->ResetMdtTrack();

  // Create negatively charged PndPidCandidate
  PndPidCandidate *cand = new PndPidCandidate();
  cand->SetCharge(-1);
  ASSERT_EQ(cand->GetCharge(), -1);

  // Run GetInfo, expect kTRUE as return if successful
  ASSERT_EQ(detector_info->GetInfo(track, cand), kTRUE);

  // PndPidCandidate should be filled with default values
  EXPECT_EQ((Int_t)cand->GetMuoQuality(), -1);
  EXPECT_EQ(cand->GetMuoIndex(), -1);
  EXPECT_EQ(cand->GetMuoModule(), 0);
  EXPECT_EQ((Int_t)cand->GetMuoMomentumIn(), 0);
  EXPECT_EQ(cand->GetMuoNumberOfLayers(), 0);
  EXPECT_EQ(cand->GetMuoIron(), 0);
  EXPECT_EQ(cand->GetMuoHits(), 0);

  // Create two more MDT hits at different positions
  TVector3 vec1(20, -35, 37);
  TVector3 vec2(-20, 35, 37);

  detector_info->SetMdtHit(10000000, vec1, kFALSE);
  detector_info->SetMdtHit(10000000, vec2, kFALSE);

  // Make sure that both hits were created
  ASSERT_EQ(detector_info->GetMdtHit()->GetEntriesFast(), 3);

  // Set MdtMapping and reset MDT track
  detector_info->MdtMapping();
  detector_info->ResetMdtTrack();

  // Run GetInfo, expect kTRUE as return if successful
  ASSERT_EQ(detector_info->GetInfo(track, cand), kTRUE);

  // Values of PndMdtHit are set in MdtInfoHelper
  EXPECT_EQ((Int_t)cand->GetMuoQuality(), 0);
  EXPECT_EQ(cand->GetMuoIndex(), 2);
  EXPECT_EQ(cand->GetMuoModule(), 1);
  EXPECT_EQ((Int_t)cand->GetMuoMomentumIn(), 0);
  EXPECT_EQ(cand->GetMuoNumberOfLayers(), 1);
  EXPECT_EQ(cand->GetMuoIron(), 0);
  EXPECT_EQ(cand->GetMuoHits(), 0);
}

