Bool_t PndPidDetectorInfo::Setup(FairRootManager *, PndPropagator *propagator, PndPidDetectorParams::DetectorParams *params)
{
  ActivateDebugNtuple(params->debug_mode);
  SetIdeal(params->ideal);
  SetVerbose(params->verbosity_level);
  SetUsePropagator(params->use_propagator);
  SetCorrPar(params->corr_par);
  SetPidHypo(params->pid_hyp);
  if (fPropagator == nullptr)
  {
    SetPropagator(propagator);
  }

  return kTRUE;
}

