InitStatus PndPidCorrelatorMod::Init() {
  
  //  cout << "InitStatus PndPidCorrelator::Init()" << endl;
  
  FairRootManager *fManager =FairRootManager::Instance();

  // Get nr of events	and digis (for progress counter)
  fNrOfEvents = ((fManager->GetInTree())->GetEntriesFast())/100;
  stoptime = 0;	

  // *** STT ***
  if (fSttMode)
    {
      if (fMixMode==kFALSE)
	{
	  fSttHit = dynamic_cast<TClonesArray *> ( fManager->GetObject("STTHit"));
	  if ( fSttHit ) 
	    {
      LOG(info) << " PndPidCorrelator::Init: Using STTHit";
      fSttMode = 2;
	    }
	  else
	    {
        LOG(warn) << " PndPidCorrelator::Init: No STT hits array! Switching STT OFF";
        fSttMode = 0;
	    } 
	}
      else
	{
	  fSttHit = dynamic_cast<TClonesArray *> (fManager->GetObject("STTHitMix"));
	  if ( fSttHit )
	    {
      LOG(info) << " PndPidCorrelator::Init: Using STTHitMix";
      fSttMode = 2;
	    }
	  else
	    {
        LOG(warn) << " PndPidCorrelator::Init: No STT hits mix array! Switching STT OFF";
        fSttMode = 0;
	    }
	}
    }
  
  // *** FTS ***
  if (fFtsMode)
    {
      if (fMixMode==kFALSE)
	{
	  fFtsHit =dynamic_cast<TClonesArray *>( fManager->GetObject("FTSHit"));
	  if ( fFtsHit ) 
	    {
      LOG(info) << " PndPidCorrelator::Init: Using FTSHit";
      fFtsMode = 2;
	    }
	  else
	    {
        LOG(warn) << " PndPidCorrelator::Init: No FTS hits array! Switching FTS OFF";
        fFtsMode = 0;
	    } 
	}
      else
	{
	  fFtsHit =dynamic_cast<TClonesArray *> (fManager->GetObject("FTSHitMix"));
	  if ( fFtsHit )
	    {
      LOG(info) << " PndPidCorrelator::Init: Using FTSHitMix";
      fFtsMode = 2;
	    }
	  else
	    {
        LOG(warn) << " PndPidCorrelator::Init: No FTS hits mix array! Switching FTS OFF";
        fFtsMode = 0;
	    }
	}
    }

  // *** MVD ***
  if (fMvdMode)
    {
      if (fMixMode==kFALSE)
	{
	  fMvdHitsStrip = dynamic_cast<TClonesArray *> ( fManager->GetObject("MVDHitsStrip"));
	  if ( ! fMvdHitsStrip ) 
	    {
      LOG(warn) << " PndPidCorrelator::Init: No MVDHitsStrip array!";
      }
	  else fMvdMode = 2;
	  
	  fMvdHitsPixel = dynamic_cast<TClonesArray *> ( fManager->GetObject("MVDHitsPixel"));
	  if ( ! fMvdHitsPixel ) 
	    {
      LOG(warn) << " PndPidCorrelator::Init: No MVDHitsPixel array!";
      }
	  else fMvdMode = 2;
	}
      else
	{
	  fMvdHitsStrip = dynamic_cast<TClonesArray *> ( fManager->GetObject("MVDHitsStripMix"));
	  if ( ! fMvdHitsStrip )
	    {
      LOG(warn) << " PndPidCorrelator::Init: No MVDHitsStripMix array!";
      }
	  else fMvdMode = 2;
	  
	  fMvdHitsPixel = dynamic_cast<TClonesArray *> (fManager->GetObject("MVDHitsPixelMix"));
	  if ( ! fMvdHitsPixel )
	    {
      LOG(warn) << " PndPidCorrelator::Init: No MVDHitsPixelMix array!";
      }
	  else fMvdMode = 2;
	}
      
      if (( ! fMvdHitsStrip ) &&  ( ! fMvdHitsPixel ))
	{
        LOG(warn) << " PndPidCorrelator::Init: No MVD hits array! Switching MVD OFF";
        fMvdMode = 0;
	}
      else
	{
    LOG(info) << " PndPidCorrelator::Init: Using MVDHit";
  }
    }
  
  // *** TOF ***
  if (fTofMode)
    {
      fTofHit = dynamic_cast<TClonesArray *> (fManager->GetObject("SciTHit"));
      if ( ! fTofHit ) 
	{
        LOG(warn) << " PndPidCorrelator::Init: No SciTHit array!";
        fTofMode = 0;
	}
      else  
	{
    LOG(info) << " PndPidCorrelator::Init: Using SciTHit";
    fTofMode = 2;
	}
    if (fIdeal)
      {
        fTofPoint = dynamic_cast<TClonesArray *> (fManager->GetObject("SciTPoint"));
        if ( ! fTofPoint )
          {
          LOG(warn) << " PndPidCorrelator::Init: No SciTPoint array!";
          fTofMode = 0;
          }
      }
    }

