}

//___________________________________________________________
PndPidCorrelatorMod::PndPidCorrelatorMod()
  : FairTask(), fMcTrack(0), fTrack(0), fTrackID(0), fTrack2(0), fTrackID2(0), fPidChargedCand(0), fPidNeutralCand(0), fMdtTrack(0), fMvdHitsStrip(0), fMvdHitsPixel(0), fTofHit(0),
    fTofPoint(0), fFtofHit(0), fFtofPoint(0), fEmcCluster(0), fEmcBump(0), fEmcDigi(0), fMdtPoint(0), fMdtHit(0), fMdtTrk(0), fDrcPoint(0), fDrcHit(0), fDskParticle(0), fSttHit(0),
    fFtsHit(0), fCorrPar(new PndPidCorrPar()), fEmcGeoPar(new PndEmcGeoPar()), fEmcErrorMatrixPar(new PndEmcErrorMatrixPar()), fEmcErrorMatrix(new PndEmcErrorMatrix()),
    fSttParameters(new PndGeoSttPar()), fEmcCalibrator(nullptr), fEmcClstCount(0), fFscClstCount(0), fDebugMode(kFALSE), fGeanePro(kTRUE), fMdtRefit(kFALSE), fMvdMode(-1),
    fSttMode(-1), fFtsMode(-1), fTofMode(-1), fFtofMode(-1), fEmcMode(-1), fMdtMode(-1), fDrcMode(-1), fDskMode(-1), fMixMode(kFALSE), fPidHyp(0), fIdealHyp(kFALSE), fFast(kFALSE),
    fSimulation(kFALSE), fIdeal(kFALSE), fCorrErrorProp(kTRUE), fFlagCut(kTRUE), fBackPropagate(kTRUE), tofCorr(0), emcCorr(0), fscCorr(0), drcCorr(0), dskCorr(0),
    fTrackBranch(""), fTrackIDBranch(""), fTrackBranch2(""), fTrackIDBranch2(""), fTrackOutBranch(""), sDir(""), sFile(""), fGeoH(nullptr), fClusterList(), fClusterQ(),
    mapMdtBarrel(), mapMdtEndcap(), mapMdtForward(), fGeanePropagator(nullptr)
{
  //---
  fPidChargedCand = new TClonesArray("PndPidCandidate");
  fPidNeutralCand = new TClonesArray("PndPidCandidate");
  sDir = "./";
  sFile = "./pidcorrelator.root";
  fGeoH = PndGeoHandling::Instance();
  
  // Resetting MDT geometry parameters
  for (Int_t mm=0; mm<3; mm++)
    for (Int_t ll=0; ll<20;ll++)
      {
	mdtLayerPos[mm][ll] = -1;
	mdtIronThickness[mm][ll] = -1;
      }
  
  Reset();
}

//___________________________________________________________
PndPidCorrelatorMod::PndPidCorrelatorMod(const char *name, const char *title)
  : FairTask(name), fMcTrack(0), fTrack(0), fTrackID(0), fTrack2(0), fTrackID2(0), fPidChargedCand(0), fPidNeutralCand(0), fMdtTrack(0), fMvdHitsStrip(0), fMvdHitsPixel(0),
    fTofHit(0), fTofPoint(0), fFtofHit(0), fFtofPoint(0), fEmcCluster(0), fEmcBump(0), fEmcDigi(0), fMdtPoint(0), fMdtHit(0), fMdtTrk(0), fDrcPoint(0), fDrcHit(0), fDskParticle(0),
    fSttHit(0), fFtsHit(0), fCorrPar(new PndPidCorrPar()), fEmcGeoPar(new PndEmcGeoPar()), fEmcErrorMatrixPar(new PndEmcErrorMatrixPar()), fEmcErrorMatrix(new PndEmcErrorMatrix()),
    fSttParameters(new PndGeoSttPar()), fEmcCalibrator(nullptr), fEmcClstCount(0), fFscClstCount(0), fDebugMode(kFALSE), fGeanePro(kTRUE), fMdtRefit(kFALSE), fMvdMode(-1),
    fSttMode(-1), fFtsMode(-1), fTofMode(-1), fFtofMode(-1), fEmcMode(-1), fMdtMode(-1), fDrcMode(-1), fDskMode(-1), fMixMode(kFALSE), fPidHyp(0), fIdealHyp(kFALSE), fFast(kFALSE),
    fSimulation(kFALSE), fIdeal(kFALSE), fCorrErrorProp(kTRUE), fFlagCut(kTRUE), fBackPropagate(kTRUE), tofCorr(0), emcCorr(0), fscCorr(0), drcCorr(0), dskCorr(0),
    fTrackBranch(""), fTrackIDBranch(""), fTrackBranch2(""), fTrackIDBranch2(""), fTrackOutBranch(""), sDir(""), sFile(""), fGeoH(nullptr), fClusterList(), fClusterQ(),
    mapMdtBarrel(), mapMdtEndcap(), mapMdtForward(), fGeanePropagator(nullptr)
{
  //---
  fPidChargedCand = new TClonesArray("PndPidCandidate");
  fPidNeutralCand = new TClonesArray("PndPidCandidate");
  sDir = "./";
  sFile = "./pidcorrelator.root";
  fGeoH = PndGeoHandling::Instance(); 
  
  // Resetting MDT geometry parameters
  for (Int_t mm=0; mm<3; mm++)
    for (Int_t ll=0; ll<20;ll++)
      {
	mdtLayerPos[mm][ll] = -1;
	mdtIronThickness[mm][ll] = -1;
      }
  
  Reset();
}

//___________________________________________________________
InitStatus PndPidCorrelatorMod::Init() {
  
  //  cout << "InitStatus PndPidCorrelator::Init()" << endl;
  
  FairRootManager *fManager =FairRootManager::Instance();

  // Get nr of events	and digis (for progress counter)
  fNrOfEvents = ((fManager->GetInTree())->GetEntriesFast())/100;
  stoptime = 0;	

  // *** STT ***
  if (fSttMode)
    {
      if (fMixMode==kFALSE)
	{
	  fSttHit = dynamic_cast<TClonesArray *> ( fManager->GetObject("STTHit"));
	  if ( fSttHit ) 
	    {
      LOG(info) << " PndPidCorrelator::Init: Using STTHit";
      fSttMode = 2;
	    }
	  else
	    {
        LOG(warn) << " PndPidCorrelator::Init: No STT hits array! Switching STT OFF";
        fSttMode = 0;
	    } 
	}
      else
	{
	  fSttHit = dynamic_cast<TClonesArray *> (fManager->GetObject("STTHitMix"));
	  if ( fSttHit )
	    {
      LOG(info) << " PndPidCorrelator::Init: Using STTHitMix";
      fSttMode = 2;
	    }
	  else
	    {
        LOG(warn) << " PndPidCorrelator::Init: No STT hits mix array! Switching STT OFF";
        fSttMode = 0;
	    }
	}
    }
  
  // *** FTS ***
  if (fFtsMode)
    {
      if (fMixMode==kFALSE)
	{
	  fFtsHit =dynamic_cast<TClonesArray *>( fManager->GetObject("FTSHit"));
	  if ( fFtsHit ) 
	    {
      LOG(info) << " PndPidCorrelator::Init: Using FTSHit";
      fFtsMode = 2;
	    }
	  else
	    {
        LOG(warn) << " PndPidCorrelator::Init: No FTS hits array! Switching FTS OFF";
        fFtsMode = 0;
	    } 
	}
      else
	{
	  fFtsHit =dynamic_cast<TClonesArray *> (fManager->GetObject("FTSHitMix"));
	  if ( fFtsHit )
	    {
      LOG(info) << " PndPidCorrelator::Init: Using FTSHitMix";
      fFtsMode = 2;
	    }
	  else
	    {
        LOG(warn) << " PndPidCorrelator::Init: No FTS hits mix array! Switching FTS OFF";
        fFtsMode = 0;
	    }
	}
    }

  // *** MVD ***
  if (fMvdMode)
    {
      if (fMixMode==kFALSE)
	{
	  fMvdHitsStrip = dynamic_cast<TClonesArray *> ( fManager->GetObject("MVDHitsStrip"));
	  if ( ! fMvdHitsStrip ) 
	    {
      LOG(warn) << " PndPidCorrelator::Init: No MVDHitsStrip array!";
      }
	  else fMvdMode = 2;
	  
	  fMvdHitsPixel = dynamic_cast<TClonesArray *> ( fManager->GetObject("MVDHitsPixel"));
	  if ( ! fMvdHitsPixel ) 
	    {
      LOG(warn) << " PndPidCorrelator::Init: No MVDHitsPixel array!";
      }
	  else fMvdMode = 2;
	}
      else
	{
	  fMvdHitsStrip = dynamic_cast<TClonesArray *> ( fManager->GetObject("MVDHitsStripMix"));
	  if ( ! fMvdHitsStrip )
	    {
      LOG(warn) << " PndPidCorrelator::Init: No MVDHitsStripMix array!";
      }
	  else fMvdMode = 2;
	  
	  fMvdHitsPixel = dynamic_cast<TClonesArray *> (fManager->GetObject("MVDHitsPixelMix"));
	  if ( ! fMvdHitsPixel )
	    {
      LOG(warn) << " PndPidCorrelator::Init: No MVDHitsPixelMix array!";
      }
	  else fMvdMode = 2;
	}
      
      if (( ! fMvdHitsStrip ) &&  ( ! fMvdHitsPixel ))
	{
        LOG(warn) << " PndPidCorrelator::Init: No MVD hits array! Switching MVD OFF";
        fMvdMode = 0;
	}
      else
	{
    LOG(info) << " PndPidCorrelator::Init: Using MVDHit";
  }
    }
  
  // *** TOF ***
  if (fTofMode)
    {
      fTofHit = dynamic_cast<TClonesArray *> (fManager->GetObject("SciTHit"));
      if ( ! fTofHit ) 
	{
        LOG(warn) << " PndPidCorrelator::Init: No SciTHit array!";
        fTofMode = 0;
	}
      else  
	{
    LOG(info) << " PndPidCorrelator::Init: Using SciTHit";
    fTofMode = 2;
	}
    if (fIdeal)
      {
        fTofPoint = dynamic_cast<TClonesArray *> (fManager->GetObject("SciTPoint"));
        if ( ! fTofPoint )
          {
          LOG(warn) << " PndPidCorrelator::Init: No SciTPoint array!";
          fTofMode = 0;
          }
      }
    }
  
  // *** FTOF ***
  if (fFtofMode)
    {
      fFtofHit = dynamic_cast<TClonesArray *> ( fManager->GetObject("FtofHit"));
      if ( ! fFtofHit ) 
	{
        LOG(warn) << " PndPidCorrelator::Init: No FtofHit array!";
        fFtofMode = 0;
	}
      else  
	{
    LOG(info) << " PndPidCorrelator::Init: Using FtofHit";
    fFtofMode = 2;
	}
    if (fIdeal)
      {
        fFtofPoint = dynamic_cast<TClonesArray *>  (fManager->GetObject("FtofPoint"));
        if ( ! fFtofPoint )
          {
          LOG(warn) << " PndPidCorrelator::Init: No FtofPoint array!";
          fFtofMode = 0;
          }
      }
    }
  
  // *** EMC ***
  if (fEmcMode)
    {
	  bool forceClusters = false;
	  bool forceBumps = false;
	  if (fEmcMode == 2) forceClusters = true;
	  if (fEmcMode == 3) forceBumps = true;

      fEmcCluster = dynamic_cast<TClonesArray *> ( fManager->GetObject("EmcCluster"));
      if ( ! fEmcCluster ) 
	{
        LOG(warn) << " PndPidCorrelator::Init: No EmcCluster array!";
        fEmcMode = 0;
	}
      else 
	{
    LOG(info) << " PndPidCorrelator::Init: Using EmcCluster";
    if (!forceBumps) fEmcMode = 2; // don't change the mode if the user wants to force the use of bumps
	}
      
      fEmcBump = dynamic_cast<TClonesArray *> (fManager->GetObject("EmcPhiBump"));
      if ( ! fEmcBump ) 
	{
        LOG(warn) << " PndPidCorrelator::Init: No EmcBump array!";
  }
      else 
	{
    LOG(info) << " PndPidCorrelator::Init: Using EmcBump";
    if (!forceClusters) fEmcMode = 3; // don't change the mode if the user wants to force the use of clusters
	}	  

      fEmcDigi = dynamic_cast<TClonesArray *> ( fManager->GetObject("EmcDigiClusterBase"));
      if ( ! fEmcDigi)
        {
        LOG(warn) << " PndPidCorrelator::Init: No EmcDigi array! No EMC E1/E9/E25 information is propagated!";
        }
    }

  // *** DRC ***
  if (fDrcMode)
    {
      fDrcHit = dynamic_cast<TClonesArray *> (fManager->GetObject("DrcHit"));
      if ( ! fDrcHit ) 
	{
        LOG(warn) << " PndPidCorrelator::Init: No DrcHit array!";
        fDrcMode = 0;
	}
      else  
	{
    LOG(info) << " PndPidCorrelator::Init: Using DrcHit";
    fDrcMode = 2;
	}
    }
  
  // *** DSK ***
  if (fDskMode)
    {
      fDskParticle = dynamic_cast<TClonesArray *> ( fManager->GetObject("DskParticle"));
      if ( ! fDskParticle )
	{
        LOG(warn) << " PndPidCorrelator::Init: No DskParticle array!";
        fDskMode = 0;
	}
      else
	{
    LOG(info) << " PndPidCorrelator::Init: Using DskParticle";
    fDskMode = 2;
	}
    }
  
  // *** MDT ***
  if (fMdtMode)
    {
      fMdtHit = dynamic_cast<TClonesArray *> (fManager->GetObject("MdtHit"));
      if ( ! fMdtHit ) 
	{
        LOG(warn) << " PndPidCorrelator::Init: No MdtHit array!";
        fMdtMode = 0;
	}
      else  
	{
    LOG(info) << " PndPidCorrelator::Init: Using MdtHit";
    fMdtMode = 2;
	}
      fMdtTrk = dynamic_cast<TClonesArray *> (fManager->GetObject("MdtTrk"));
      if ( ! fMdtTrk ) 
	{
        LOG(warn) << " PndPidCorrelator::Init: No MdtTrk array!";
  }
      else  
	{
    LOG(info) << " PndPidCorrelator::Init: Using MdtTrk";
    fMdtMode = 3;
	}
    }
  
  if (fIdeal)
    {
    LOG(info) << " PndPidCorrelator::Init: Using MonteCarlo correlation";
    fTofPoint = dynamic_cast<TClonesArray *>(fManager->GetObject("TofPoint"));
    if (!fTofPoint) {
      LOG(warn) << " PndPidCorrelator::Init: No TofPoint array!";
      fTofMode = 0;
	}
      else  
	{
    LOG(info) << " PndPidCorrelator::Init: Using TofPoint";
  }
      fDrcPoint = dynamic_cast<TClonesArray *> (fManager->GetObject("DrcBarPoint"));
      if ( ! fDrcPoint ) 
	{
        LOG(warn) << " PndPidCorrelator::Init: No DrcBarPoint array!";
        fDrcMode = 0;
	}
      else  
	{
    LOG(info) << " PndPidCorrelator::Init: Using DrcPoint";
  }
      fMdtPoint = dynamic_cast<TClonesArray *> ( fManager->GetObject("MdtPoint"));
      if ( ! fMdtPoint ) 
	{
        LOG(warn) << " PndPidCorrelator::Init: No MdtPoint array!";
        fMdtMode = 0;
	}
      else  
	{
    LOG(info) << " PndPidCorrelator::Init: Using MdtPoint";
  }
    }
  
  Register();
  
  fCorrPar->printParams();
  
  if (fGeanePro)
    {
    LOG(info) << " PndPidCorrelator::Init: Using Geane for Track propagation";
    fGeanePropagator = new FairGeanePro();

    if (!fCorrErrorProp) {
      LOG(info) << " PndPidCorrelator::Init: Switching OFF Geane error propagation";
      fGeanePropagator->PropagateOnlyParameters();
	}
      if (fIdealHyp)
	{
	  fMcTrack = dynamic_cast<TClonesArray *> (fManager->GetObject("MCTrack"));
	  if ( ! fMcTrack ) {
      LOG(info) << " PndPidCorrelator::Init: No PndMcTrack array! No ideal pid hypothesis is possible!";
      return kERROR;
	  }
	  if (fTrackIDBranch=="") {
      LOG(info) << " PndPidCorrelator::Init: No TrackID Branch name! No ideal pid hypothesis is possible!";
      return kERROR;
	  }
	}
      else
	{
	  switch (abs(fPidHyp))
	    {
	    case 0:
        LOG(info) << " PndPidCorrelator::Init: No PID set -> Using default PION hypothesis";
        fPidHyp = 211;
	      break;
        
	    case 11:
        LOG(info) << " PndPidCorrelator::Init: Using ELECTRON hypothesis";
        fPidHyp = -11;
	      break;
        
	    case 13:
        LOG(info) << " PndPidCorrelator::Init: Using MUON hypothesis";
        fPidHyp = -13;
	      break;
        
	    case 211:
        LOG(info) << " PndPidCorrelator::Init: Using PION hypothesis";
        fPidHyp = 211;
	      break;
        
	    case 321:
        LOG(info) << " PndPidCorrelator::Init: Using KAON hypothesis";
        fPidHyp = 321;
	      break;
        
	    case 2212:
        LOG(info) << " PndPidCorrelator::Init: Using PROTON hypothesis";
        fPidHyp = 2212;
	      break;
        
	    default:
        LOG(info) << " PndPidCorrelator::Init: Not recognised PID set -> Using default PION hypothesis";
        fPidHyp = 211;
	      break;
	    }
	}
    }
  else
    {
      return kFATAL;
    }
  
  if (fMdtMode>0)
    {
      if (!MdtGeometry())
	{
        LOG(warn) << " PndPidCorrelator::Init: No MDT geometry ???";
        fMdtMode = 0;
	}
    }
  
  if   (fMdtRefit)
    {
      fFitter = new PndRecoKalmanFit();
      fFitter->SetGeane(fGeanePro);
      fFitter->SetNumIterations(1);
      if (!fFitter->Init()) return kFATAL;
    } 
  
  if (fDebugMode)
    {
      r = TFile::Open(sDir+sFile,"RECREATE");
    
      tofCorr = new TNtuple("tofCorr","TRACK-TOF Correlation",
			    "track_x:track_y:track_z:track_phi:track_p:track_charge:track_theta:track_z0:tof_x:tof_y:tof_z:tof_phi:chi2:dphi:len:glen");
      ftofCorr = new TNtuple("ftofCorr","TRACK-FTOF Correlation",
                            "track_x:track_y:track_z:ver_x:ver_y:ver_z:ver_px:ver_py:ver_pz:track_p:track_charge:track_theta:track_z0:tof_x:tof_y:tof_z:chi2:len:glen:tlen");
      emcCorr = new TNtuple("emcCorr","TRACK-EMC Correlation",
			    "track_x:track_y:track_z:track_phi:track_p:track_charge:track_theta:track_z0:emc_x:emc_y:emc_z:emc_phi:chi2:dphi:emc_ene:glen:emc_mod");
      fscCorr = new TNtuple("fscCorr","TRACK-FSC Correlation",
			    "track_x:track_y:track_z:track_phi:track_p:track_charge:track_theta:track_z0:emc_x:emc_y:emc_z:emc_phi:chi2:dphi:emc_ene:glen:emc_mod");
      mdtCorr = new TNtuple("mdtCorr","TRACK-MDT Correlation",
			    "track_x:track_y:track_z:track_dx:track_dy:track_dz:track_phi:track_p:track_charge:track_theta:track_z0:mdt_x:mdt_y:mdt_z:mdt_phi:mdt_p:chi2:mdt_mod:dphi:glen:mdt_count:nhits");
      drcCorr = new TNtuple("drcCorr","TRACK-DRC Correlation",
			    "track_x:track_y:track_z:track_phi:track_p:track_charge:track_theta:track_z0:drc_x:drc_y:drc_phi:chi2:drc_thetac:drc_nphot:dphi:glen:flag");
      dskCorr = new TNtuple("dskCorr","TRACK-DSK Correlation",
			    "track_x:track_y:track_z:track_phi:track_p:track_charge:track_theta:track_z0:dsk_x:dsk_y:dsk_z:dsk_phi:chi2:dsk_thetac:dsk_nphot:dphi:glen:track_lx:track_ly:track_lz:track_xp:flag");
      LOG(info) << " PndPidCorrelator::Init: Filling Debug histograms";
    }
	
  // Set Parameters for Emc error matrix 
  if (fEmcMode>0) 
  {
    if (fEmcErrorMatrixPar->IsValid())
      {
        fEmcErrorMatrix->Init(fEmcErrorMatrixPar->GetParObject());
        //std::cout<<"PndPidCorrelator: Emc error matrix is read from RTDB"<<std::endl;
      } else
      {
        Int_t emcGeomVersion=fEmcGeoPar->GetGeometryVersion();
        fEmcErrorMatrix->InitFromFile(emcGeomVersion);
        fEmcErrorMatrixPar->SetErrorMatrixObject(fEmcErrorMatrix->GetParObject());
        //std::cout<<"PndPidCorrelator: Emc error matrix is read from file"<<std::endl;
      }
    fEmcCalibrator= PndEmcClusterCalibrator::MakeEmcClusterCalibrator(1, 3);	
  }

  if (fFast)  cout << "-W- PndPidCorrelator::Init: Using fast correlator!!" << endl;

  cout << "USING EMC MODE: " << fEmcMode << std::flush;
  if (fEmcMode==2) cout << " (clusters)" << endl;
  else if (fEmcMode==3) cout << " (bumps)" << endl;

  LOG(info) << " PndPidCorrelator::Init: Success!";
  fEventCounter = 1;
  return kSUCCESS;
}

//______________________________________________________
void PndPidCorrelatorMod::SetParContainers() {
  
  // Get run and runtime database
  FairRun* run = FairRun::Instance();
  if ( ! run ) Fatal("PndPidCorrelator:: SetParContainers", "No analysis run");
  
  FairRuntimeDb* db = run->GetRuntimeDb();
  if ( ! db ) Fatal("PndPidCorrelator:: SetParContainers", "No runtime database");
  
  // Get PID Correlation parameter container
  fCorrPar = (PndPidCorrPar*) db->getContainer("PndPidCorrPar");
  
  // Get Emc geometry parameter container
  fEmcGeoPar = (PndEmcGeoPar*) db->getContainer("PndEmcGeoPar");
  
  // Get Emc error matrix parameter container
  fEmcErrorMatrixPar = (PndEmcErrorMatrixPar*) db->getContainer("PndEmcErrorMatrixPar");

  // Get Stt parameter
  fSttParameters = (PndGeoSttPar*) db->getContainer("PndGeoSttPar");
  fFtsParameters = (PndGeoFtsPar*) db->getContainer("PndGeoFtsPar");
}
//______________________________________________________
void PndPidCorrelatorMod::Exec(Option_t * option) {
  //-
  Reset();
  fTimer.Start(kFALSE);

  if (fEmcMode>0)
    {
      PndEmcCluster *tmp_cluster;
      for(Int_t i=0; i < fEmcCluster->GetEntriesFast();i++)
	{
	  tmp_cluster = (PndEmcCluster*)fEmcCluster->At(i);
	  if(tmp_cluster->GetModule() < 5 && tmp_cluster->GetModule() >0)
	    {
	      fEmcClstCount++;
	    }
	  if(tmp_cluster->GetModule() == 5)
	    {
	      fFscClstCount++;
	    }
	}
      ResetEmcQ();
	  if (fVerbose>2) {
      	cout << " - Number of Clusters for pid: ";
      	cout << " EMC: " << fEmcClstCount;
      	cout << " FSC: " << fFscClstCount;
	  }
    }
  if (fVerbose>2) cout<<endl;

  if (fEventCounter-1==nPidProg*fNrOfEvents && nPidProg < 101) {

	double time = fTimer.RealTime();
	int remtime = (100-nPidProg)*time/nPidProg;
	cout << "\r                                                                               " << std::flush;
  	cout << "\r[INFO\t] PndPidCorrelator: " << nPidProg << "\% completed (about " << remtime << " seconds remaining)" << std::flush;	
	nPidProg += 1;
  }

  //if (fEventCounter%100 == 0) cout << "\r[INFO\t] PndPidCorrelator - Event: " << fEventCounter << std::flush;

 // if (fTrack)     ConstructChargedCandidate();
  if ((fEmcMode>0)  && (!fFast)) ConstructNeutralCandidate();
  fEventCounter++;

}

//______________________________________________________
void PndPidCorrelatorMod::ConstructChargedCandidate() {
  //-
  //FIXME: Use Clear() to save time. 
  //Call Delete() only for too busy events to save Memory
  fPidChargedCand->Delete();
  if (fMdtRefit) fMdtTrack->Delete();
  if (fMdtMode>0) MdtMapping();
  
  Int_t nTracks = fTrack->GetEntriesFast();
  for (Int_t i = 0; i < nTracks; i++) {
    PndTrack* track = (PndTrack*) fTrack->At(i);
    Int_t ierr = 0;
    FairTrackParP par = track->GetParamLast();
    if ((par.GetMomentum().Mag()<0.05) || (par.GetMomentum().Mag()>15.) )continue; // cut low and high momenta
    if ((fFlagCut) && (track->GetFlag()<=0)) continue; // cut flag<=0
    FairTrackParH *helix = new FairTrackParH(&par, ierr);
    
    PndPidCandidate* pidCand = 	new PndPidCandidate();
    if (fTrackIDBranch!="")
      {
	PndTrackID* trackID = (PndTrackID*) fTrackID->At(i);
	if (trackID->GetNCorrTrackId()>0)
	  {
	    pidCand->SetMcIndex(trackID->GetCorrTrackID());
	    if (fIdealHyp)
	      {
		PndMCTrack *mcTrack = (PndMCTrack*)fMcTrack->At(trackID->GetCorrTrackID());
		if ( ! mcTrack ) 
		  {
		    fPidHyp = 211;
        LOG(info) << " PndPidCorrelator::ConstructChargedCandidate: PndMCTrack does not exist!! (why?) -> let's try with pion hyp ";
      }
                else
		  {
		    fPidHyp = abs(mcTrack->GetPdgCode());
		  }
                if (fPidHyp>=100000000)
                  {
                    fPidHyp = 211;
                    LOG(info) << " PndPidCorrelator::ConstructChargedCandidate: Track is an ion (PDGCode>100000000) -> let's try with pion hyp";
                  }

		if ( abs(fPidHyp)==13 ) fPidHyp = -13;
		if ( abs(fPidHyp)==11 ) fPidHyp = -11;
	      }
	  }
      } else { // added for PndAnalysis, TODO: remove after Fairlinks work with Associators
      PndTrackCand trackCand = track->GetTrackCand();
      pidCand->SetMcIndex(trackCand.getMcTrackId());
    }
    pidCand->SetTrackIndex(i);
    pidCand->SetTrackBranch(FairRootManager::Instance()->GetBranchId(fTrackBranch));
    pidCand->AddLink(FairLink(fTrackBranch, i));
    if (!GetTrackInfo(track, pidCand)) continue;
    if ( (fMvdMode==2) && ((fMvdHitsStrip->GetEntriesFast()+fMvdHitsPixel->GetEntriesFast())>0) ) GetMvdInfo(track, pidCand); 
    if ( (fSttMode == 2) && (fSttHit    ->GetEntriesFast()>0) ) GetSttInfo(track, pidCand);
    GetGemInfo(track, pidCand);
    if (!fFast)
      {
	if ( (fTofMode==2) && (fTofHit    ->GetEntriesFast()>0) ) GetTofInfo(helix, pidCand);
	if ( (fEmcMode>0)  && (fEmcClstCount>0) ) GetEmcInfo(helix, pidCand);
	if ( (fMdtMode>0)  && (fMdtHit    ->GetEntriesFast()>0) ) GetMdtInfo(track, pidCand);  
	if ( (fDrcMode>0)  && (fDrcHit    ->GetEntriesFast()>0) ) GetDrcInfo(helix, pidCand);
	if ( (fDskMode>0)  && (fDskParticle->GetEntriesFast()>0)) GetDskInfo(helix, pidCand); 
      }
    AddChargedCandidate(pidCand);
  } 
  
  if (fTrackBranch2!="")
    {
      Int_t nTracks2 = fTrack2->GetEntriesFast();
      for (Int_t i = 0; i < nTracks2; i++) {
	PndTrack* track = (PndTrack*) fTrack2->At(i);
	Int_t ierr = 0;
	FairTrackParP par = track->GetParamLast();
	if ((par.GetMomentum().Mag()<0.1) || (par.GetMomentum().Mag()>20.) )continue; // cut low and high momenta
	if ((fFlagCut) && (track->GetFlag()<=0)) continue; // cut flag<=0
	FairTrackParH *helix = new FairTrackParH(&par, ierr);
      
	PndPidCandidate* pidCand =  new PndPidCandidate();
	if (fTrackIDBranch2!="")
	  {
	    PndTrackID* trackID = (PndTrackID*) fTrackID2->At(i);
	    if (trackID->GetNCorrTrackId()>0)
	      {
		pidCand->SetMcIndex(trackID->GetCorrTrackID());
		if (fIdealHyp)
		  {
		    PndMCTrack *mcTrack = (PndMCTrack*)fMcTrack->At(trackID->GetCorrTrackID());
		    if ( ! mcTrack ) 
		      {
			fPidHyp = 211;
      LOG(info) << " PndPidCorrelator::ConstructChargedCandidate: PndMCTrack does not exist!! (why?) -> let's try with pion hyp ";
          }
		    else
		      {
			fPidHyp = abs(mcTrack->GetPdgCode());
		      }
		    if (fPidHyp>=100000000)
		      {
			fPidHyp = 211;
      LOG(info) << " PndPidCorrelator::ConstructChargedCandidate: Track is an ion (PDGCode>100000000) -> let's try with pion hyp";
          }
		    
		    if ( abs(fPidHyp)==13 ) fPidHyp = -13;
		    if ( abs(fPidHyp)==11 ) fPidHyp = -11;
		  }
	      }
	  } else { // added for PndAnalysis, TODO: remove after Fairlinks work with Associators
	  PndTrackCand trackCand = track->GetTrackCand();
	  pidCand->SetMcIndex(trackCand.getMcTrackId());
	}
	pidCand->SetTrackIndex(i);
        pidCand->SetTrackBranch(FairRootManager::Instance()->GetBranchId(fTrackBranch2));
	pidCand->AddLink(FairLink("PndTrack", i));
	if (!GetTrackInfo(track, pidCand)) continue;
	if ( (fMvdMode==2) && ((fMvdHitsStrip->GetEntriesFast()+fMvdHitsPixel->GetEntriesFast())>0) ) GetMvdInfo(track, pidCand); 
	if ( (fFtsMode == 2) && (fFtsHit    ->GetEntriesFast()>0) ) GetFtsInfo(track, pidCand); 
	GetGemInfo(track, pidCand);
	if (!fFast)
	  {
	    if ( (fFtofMode==2) && (fFtofHit->GetEntriesFast()>0) ) GetFtofInfo(helix, pidCand);
	    if ( (fEmcMode>0)  && (fFscClstCount>0) ) GetFscInfo(helix, pidCand);
	    //if ( (fMdtMode>0)  && (fMdtHit    ->GetEntriesFast()>0) ) GetMdtInfo(track, pidCand);
	    if (mapMdtForward.size()>0)  GetFMdtInfo(&par, pidCand);
	  } // end of fast mode
	AddChargedCandidate(pidCand);
      }
    }
  
}

//______________________________________________________
