	  //if (fClusterList[bump->GetClusterIndex()]) continue; // skip correlated clusters
	  clu = (PndEmcCluster*)fEmcCluster->At(bump->GetClusterIndex());
          //quality = fClusterQ[bump->GetClusterIndex()];
	}

// ----- Overwrite existing digiArray and fill with digis fetched via FairLinks ----//
/*int NrOfDigis = fEmcDigi->GetEntries();
cout << "Number of Digis (cluster "<< i << "): " << fEmcDigi->GetEntries() << endl;
for (int bf=0; bf<fEmcDigi->GetEntries(); bf++) {
	PndEmcDigi *digi = (PndEmcDigi *) fEmcDigi->At(bf);
	cout << digi->GetEnergy() << " ";
}
cout << "\nDeleting digi array..." << endl;
	fEmcDigi->Delete();
cout << "Getting linked digis... ";
std::cout << *clu->GetPointerToLinks() << std::endl;
	FairMultiLinkedData digiLinks = clu->GetLinksWithType(FairRootManager::Instance()->GetBranchId("EmcDigiSorted"));
cout << digiLinks.GetNLinks() << " found." << endl;
if (digiLinks.GetNLinks() < NrOfDigis) continue;
	for (Int_t j=0; j<digiLinks.GetNLinks(); j++){
cout << "digi #" << j << ": ";
		PndEmcDigi* myDigi = (PndEmcDigi*)FairRootManager::Instance()->GetCloneOfLinkData(digiLinks.GetLink(j));
		if(myDigi) {
cout << myDigi->GetEnergy() << "(L) ";
			PndEmcDigi* newDigi = new((*fEmcDigi)[fEmcDigi->GetEntriesFast()]) PndEmcDigi(*myDigi); 
			delete(myDigi);

		} else {
			std::cout << "-E in PndPidCorrelatorMod::ConstructNeutralCandidate() FairLink " << digiLinks.GetLink(j) << " to EmcDigi delivers null" << std::endl;
		}
	}
cout << endl;*/
// ------------------------ //

      TVector3 vtx(0,0,0);
      TVector3 v1=bump->where();
      TVector3 p3;
      p3.SetMagThetaPhi(fEmcCalibrator->Energy(bump), v1.Theta(), v1.Phi());
      TLorentzVector lv(p3,p3.Mag());
      TMatrixD covP4=fEmcErrorMatrix->Get4MomentumErrorMatrix(*clu);
      TMatrixD covP7=fEmcErrorMatrix->GetErrorP7(*clu);
 
// *** Real PID correlator compares the bump location to the vertex of digi tracks here *** //
// omitted for testing purposes (and because it leads to crashes atm) -> set vertex location to IP //
      
	 // std::cout << "Constructing pidCand (EMC)" << endl;
      PndPidCandidate* pidCand = new PndPidCandidate(0, vtx, lv);
