      pidCand->SetEmcCalEnergy(fEmcCalibrator->Energy(bump));
      pidCand->SetEmcIndex(i);
      pidCand->SetEmcModule(bump->GetModule());
      pidCand->SetEmcNumberOfCrystals(bump->NumberOfDigis());
      pidCand->SetEmcNumberOfBumps(clu->NBumps());
