    micro->SetMvdHits(numhits);

    // micro->SetSttHitIndexArray(stthits, stt_hitidx);
    // micro->SetTpcHitIndexArray(tpchits, tpc_hitidx);

    ///****** Extrapolation to primary vertex ******

    // rep=tr1->getTrackRep(0)->clone();
    unsigned int hid;
