class TCandList;
class TCandidate;
class TFitParams;

int run_ana_eta_c_stt(int nevts = 0, bool usePID = true)
{
  TString OutFile = "etac_histo_stt.root";

  enum DetectorId { kDCH, kDRC, kDSK, kEMC, kGEM, kLUMI, kMDT, kMVD, kRPC, kSTT, kTPC, kTOF, kFTS, kHYPG, kHYP };
