	};
	nt->Fill(ntuple_nt);

      } // end of MC loop
    mc_fourpi = mc_k[0] + mc_k[1];
    reco_fourpi = reco_k[0] + reco_k[1];

    Float_t ntuple_evt[] = {
      j, stt_mccount, tpc_mccount, reco_count, reco_ctcount, cand_array->GetEntriesFast(),
