	};
	nt->Fill(ntuple_nt);

      } // end of MC loop
    mc_fourpi = mc_k[0] + mc_k[1]+mc_k[2]+mc_k[3];
    reco_fourpi = reco_k[0] + reco_k[1]+reco_k[2]+reco_k[3];

