void PndFastSim::Register()
{
  //---

  fMcCandidates = new TClonesArray("RhoCandidate");
  FairRootManager::Instance()->Register("PndMcTracks", "FastSim", fMcCandidates, GetPersistency());

  fPidChargedCand = new TClonesArray("PndPidCandidate");
  FairRootManager::Instance()->Register("PidChargedCand", "FastSim", fPidChargedCand, GetPersistency());

  fPidNeutralCand = new TClonesArray("PndPidCandidate");
  FairRootManager::Instance()->Register("PidNeutralCand", "FastSim", fPidNeutralCand, GetPersistency());

  fPidChargedProb = new TClonesArray("PndPidProbability");
  FairRootManager::Instance()->Register("PidChargedProbability", "FastSim", fPidChargedProb, GetPersistency());

  fPidNeutralProb = new TClonesArray("PndPidProbability");
  FairRootManager::Instance()->Register("PidNeutralProbability", "FastSim", fPidNeutralProb, GetPersistency());

  fEventInfo = new TClonesArray("PndEventInfo");
  FairRootManager::Instance()->Register("PndEventSummary", "FastSim", fEventInfo, GetPersistency());

  for (FsmAbsDetList::iterator iter = fDetList.begin(); iter != fDetList.end(); iter++) {
    PndFsmAbsDet *det = *iter;
    if (!det->doesPid())
      continue;
    TString detname = det->detName();
    TString arrayname = detname;
    arrayname += "Probability";
    TClonesArray *tmparray = new TClonesArray("PndPidProbability");
    FairRootManager::Instance()->Register(arrayname.Data(), "FastSim", tmparray, GetPersistency());
    fPidArrayList[detname] = tmparray;
    // std::cout<<"registered pid TCA with name "<<detname.Data()<<std::endl;
  }
}

// -----   Public method Init   --------------------------------------------
InitStatus PndFastSim::Init()
{

  if (fVb > 3)
    cout << " Inside the Init function****" << endl;

  Register();
  cout << "\n\n******   DETECTOR SETUP SUMMARY    ***************\n\n";
  for (FsmAbsDetList::iterator iter = fDetList.begin(); iter != fDetList.end(); iter++) {
    cout << endl << "----------------------------" << endl;
    PndFsmAbsDet *det = *iter;
    det->print(std::cout);
  }
  cout << "\n\n******   DETECTOR SETUP SUMMARY    ***************\n\n";

  evtcnt = 0;

  // for the time being, this is the matrix of correlation
  // coefficients, it is later scaled by the track errors
  // d0                 phi0                omega               z0                  dandip
  fRho(0, 0) = 1;
  fRho(0, 1) = -0.9243;
  fRho(0, 2) = 0.3087;
  fRho(0, 3) = -0.01743;
  fRho(0, 4) = 0.009165; // d0
  fRho(1, 0) = -0.9243;
  fRho(1, 1) = 1;
  fRho(1, 2) = -0.4189;
  fRho(1, 3) = -0.00552;
  fRho(1, 4) = -0.00873; // phi0
  fRho(2, 0) = 0.3087;
  fRho(2, 1) = -0.4189;
  fRho(2, 2) = 1;
  fRho(2, 3) = 0.02094;
  fRho(2, 4) = -0.01742; // omega
  fRho(3, 0) = -0.01743;
  fRho(3, 1) = -0.00552;
  fRho(3, 2) = 0.02094;
  fRho(3, 3) = 1;
  fRho(3, 4) = -0.9327; // z0
  fRho(4, 0) = 0.009165;
  fRho(4, 1) = -0.00873;
  fRho(4, 2) = -0.01742;
  fRho(4, 3) = -0.9327;
  fRho(4, 4) = 1; // tandip
  // and this is the square root of fRho
  // needed to correlate the track params
  // d0                 phi0                 omega                z0                  dandip
  fEta(0, 0) = 1; // d0
  fEta(1, 0) = -0.9243;
  fEta(1, 1) = 0.3817; // phi0
  fEta(2, 0) = 0.3087;
  fEta(2, 1) = -0.35;
  fEta(2, 2) = 0.8844; // omega
  fEta(3, 0) = -0.01743;
  fEta(3, 1) = -0.05667;
  fEta(3, 2) = 0.007335;
  fEta(3, 3) = 0.9982; // z0
  fEta(4, 0) = 0.009165;
  fEta(4, 1) = -6.781e-4;
  fEta(4, 2) = -0.02316;
  fEta(4, 3) = -0.9341;
  fEta(4, 4) = 0.3562; // tandip

  // parametrization for bremsstrahlung (based on Crystal Ball function tail)
  fBremsEnergy = new TF1("fBremsEnergy", "[0]*pow([3]/[4],[3])*exp(-0.5*[4]^2)/pow((x-[1])/[2]+[3]/[4]-[4],[3])");
  fBremsEnergy->SetParameters(1, 0.005, 0.0311, 1.05, 1.04);
  fBremsEnergy->SetRange(0.03, 0.9); // valid between 3% and 90% energy loss through bremsstrahlung

  // Create and register output array
  LOG(info) << " PndFastSim: Intialization successfull";

  return kSUCCESS;
}

