			if (((m_phi1>1.02-0.02)&&(m_phi1<1.02+0.02))&&
				((m_phi2>1.02-0.02)&&(m_phi2<1.02+0.02)))
			{
				h_etac_phimass_vtx->Fill(etacvtx_mass);
				if ((etacvtx_mass>2.9)&&(etacvtx_mass<3.06))
					n_reco_vtx++;
			}

		}
////////////////////////////////////////////////////////////////////
