	  }
      }
    }


    n_removed=0;
    ii=0;
    for (l=0;l<pm.GetLength();++l) {
      ii=l-n_removed;
      if (pm[ii].GetMicroCandidate().GetMcIndex()>-1){
	PndMCTrack *mcTrack = (PndMCTrack*)mc_array->At(pm[ii].GetMicroCandidate().GetMcIndex());
	if (mcTrack!=0)
	  {
	    if ((mcTrack->GetPdgCode()!=-211) || (mcTrack->GetMotherID()!=-1))
	      {
