      hvtxresZ->Fill(mcVertex.Z() - bestPos.Z());

      if (((m_phi1 > 1.02 - 0.02) && (m_phi1 < 1.02 + 0.02)) && ((m_phi2 > 1.02 - 0.02) && (m_phi2 < 1.02 + 0.02))) {
