	  clu = (PndEmcCluster*)fEmcCluster->At(bump->GetClusterIndex());
          //quality = fClusterQ[bump->GetClusterIndex()];
	}

// ----- Overwrite existing digiArray and fill with digis fetched via FairLinks ----//
/*int NrOfDigis = fEmcDigi->GetEntries();
cout << "Number of Digis (cluster "<< i << "): " << fEmcDigi->GetEntries() << endl;
for (int bf=0; bf<fEmcDigi->GetEntries(); bf++) {
