PndFsmResponse *PndFastSim::sumResponse(FsmResponseList respList)
{

  bool detected = false;

  double dE = 0.0;
  double dp = 0.0;
  double dtheta = 0.0;
  double dphi = 0.0;
  double dt = 0.0;
  double dm = 0.0;

  double m2 = 0;
  double MvddEdx = 0;
  double SttdEdx = 0;
  double DrcDiscThtc = 0;
  double DrcBarrelThtc = 0;
  double RichThtc = 0;
  double EmcEcal = 0;
  double MuoIron = 0;

  double m2Err = 0;
  double MvddEdxErr = 0;
  double SttdEdxErr = 0;
  double DrcDiscThtcErr = 0;
  double DrcBarrelThtcErr = 0;
  double RichThtcErr = 0;

  double dVx = 0.0;
  double dVy = 0.0;
  double dVz = 0.0;

  double LH_e = 1.0;
  double LH_mu = 1.0;
  double LH_pi = 1.0;
  double LH_K = 1.0;
  double LH_p = 1.0;

  double val = 0.0;

  PndFsmResponse *allResponse = new PndFsmResponse();

  if (fVb > 3)
    cout << " *** SINGLE RESPONSES ***" << endl << "--------------------------------------" << endl;

  for (FsmResponseList::iterator riter = respList.begin(); riter != respList.end(); riter++) {
    PndFsmResponse *resp = *riter;

    if (fVb > 3)
      resp->print(cout);

    if (resp->detector()->detName() == "IdealPid")
      continue; // don't use ideal PID

    detected = detected | resp->detected();

    if (resp->detected()) {
      if (fabs(val = resp->dE()) > 1e-8)
        dE += 1 / (val * val);
      if (fabs(val = resp->dp()) > 1e-8)
        dp += 1 / (val * val);
      if (fabs(val = resp->dtheta()) > 1e-8)
        dtheta += 1 / (val * val);
      if (fabs(val = resp->dphi()) > 1e-8)
        dphi += 1 / (val * val);

      if (fabs(val = resp->dt()) > 1e-8)
        dt += val * val;
      if (fabs(val = resp->dm()) > 1e-8)
        dm = val;
      if (fabs(val = resp->m2()) > 1e-11)
        m2 = val;
      if (fabs(val = resp->MvddEdx()) > 1e-11)
        MvddEdx = val;
      if (fabs(val = resp->SttdEdx()) > 1e-11)
        SttdEdx = val;
      if (fabs(val = resp->DrcDiscThtc()) > 1e-11)
        DrcDiscThtc = val;
      if (fabs(val = resp->DrcBarrelThtc()) > 1e-11)
        DrcBarrelThtc = val;
      if (fabs(val = resp->RichThtc()) > 1e-11)
        RichThtc = val;
      if (fabs(val = resp->EmcEcal()) > 1e-11)
        EmcEcal = val;
      if (fabs(val = resp->MuoIron()) > 1e-11)
        MuoIron = val;

      if (fabs(val = resp->m2Err()) > 1e-11)
        m2Err = val;
      if (fabs(val = resp->MvddEdxErr()) > 1e-11)
        MvddEdxErr = val;
      if (fabs(val = resp->SttdEdxErr()) > 1e-11)
        SttdEdxErr = val;
      if (fabs(val = resp->DrcDiscThtcErr()) > 1e-11)
        DrcDiscThtcErr = val;
      if (fabs(val = resp->DrcBarrelThtcErr()) > 1e-11)
        DrcBarrelThtcErr = val;
      if (fabs(val = resp->RichThtcErr()) > 1e-11)
        RichThtcErr = val;

      if (fabs(val = resp->dV().X()) > 1e-11)
        dVx += 1 / (val * val);
      if (fabs(val = resp->dV().Y()) > 1e-11)
        dVy += 1 / (val * val);
      if (fabs(val = resp->dV().Z()) > 1e-11)
        dVz += 1 / (val * val);

      double rawLHe = resp->LHElectron();
      double rawLHmu = resp->LHMuon();
      double rawLHpi = resp->LHPion();
      double rawLHK = resp->LHKaon();
      double rawLHp = resp->LHProton();

      double sumRaw = rawLHe + rawLHmu + rawLHpi + rawLHK + rawLHp;

      if (sumRaw > 0) {
        rawLHe /= sumRaw;
        rawLHmu /= sumRaw;
        rawLHpi /= sumRaw;
        rawLHK /= sumRaw;
        rawLHp /= sumRaw;
        LH_e *= rawLHe;
        LH_mu *= rawLHmu;
        LH_pi *= rawLHpi;
        LH_K *= rawLHK;
        LH_p *= rawLHp;
      } else {
        LH_e *= 0.2;
        LH_mu *= 0.2;
        LH_pi *= 0.2;
        LH_K *= 0.2;
        LH_p *= 0.2;
      }

      // here a weighted Likelihood evaluation has to be done

      /*
      if (val = rawLHe)  LH_e  == 0.0 ? LH_e  = val : LH_e  *= val;
      if (val = rawLHmu) LH_mu == 0.0 ? LH_mu = val : LH_mu *= val;
      if (val = rawLHpi) LH_pi == 0.0 ? LH_pi = val : LH_pi *= val;
      if (val = rawLHK)  LH_K  == 0.0 ? LH_K  = val : LH_K  *= val;
      if (val = rawLHp)  LH_p  == 0.0 ? LH_p  = val : LH_p  *= val;
      */
    }
  }

  double sumLH = LH_e + LH_mu + LH_pi + LH_K + LH_p;

  if (sumLH > 0) {
    LH_e /= sumLH;
    LH_mu /= sumLH;
    LH_pi /= sumLH;
    LH_K /= sumLH;
    LH_p /= sumLH;
  } else {
    LH_e = 0.2;
    LH_mu = 0.2;
    LH_pi = 0.2;
    LH_K = 0.2;
    LH_p = 0.2;
  }

  allResponse->setDetected(detected);
  allResponse->setdE(dE > 0. ? 1 / sqrt(dE) : 0.0);
  allResponse->setdp(dp > 0. ? 1 / sqrt(dp) : 0.0);
  allResponse->setdtheta(dtheta > 0. ? 1 / sqrt(dtheta) : 0.0);
  allResponse->setdphi(dphi > 0. ? 1 / sqrt(dphi) : 0.0);
  allResponse->setdt(sqrt(dt));
  allResponse->setdm(dm);

  allResponse->setm2(m2, m2Err);
  allResponse->setMvddEdx(MvddEdx, MvddEdxErr);
  allResponse->setSttdEdx(SttdEdx, SttdEdxErr);

  allResponse->setDrcDiscThtc(DrcDiscThtc, DrcDiscThtcErr);
  allResponse->setDrcBarrelThtc(DrcBarrelThtc, DrcBarrelThtcErr);
  allResponse->setRichThtc(RichThtc, RichThtcErr);
  allResponse->setEmcEcal(EmcEcal);
  allResponse->setMuoIron(MuoIron);

  if (dVx > 0.)
    dVx = 1. / sqrt(dVx);
  else
    dVx = 0.0;
  if (dVy > 0.)
    dVy = 1. / sqrt(dVy);
  else
    dVy = 0.0;
  if (dVz > 0.)
    dVz = 1. / sqrt(dVz);
  else
    dVz = 0.0;

  allResponse->setdV(dVx, dVy, dVz);

  allResponse->setLHElectron(LH_e);
  allResponse->setLHMuon(LH_mu);
  allResponse->setLHPion(LH_pi);
  allResponse->setLHKaon(LH_K);
  allResponse->setLHProton(LH_p);

  if (fVb > 2)
    cout << "--------------------------------------" << endl << "*** OVERALL RESPONSE ***" << endl << "--------------------------------------" << endl;
  if (fVb > 2)
    allResponse->print(cout);
  if (fVb > 2)
    cout << "--------------------------------------" << endl;

  return allResponse;
}

void PndFastSim::UpdateGammaHit(PndFsmTrack *t)
{
  TVector3 hitpos = t->stopVtx();
  double z = hitpos.z();
  if (z == 0.) { // barrel - TODO convention to set z=0 initially.
    if (fabs(t->p4().Perp()) < 1e-9)
      return;
    double perpscale = hitpos.Perp() / t->p4().Perp();
    double x = t->p4().Px() * perpscale;
    double y = t->p4().Py() * perpscale;
    z = t->p4().Pz() * perpscale;
    hitpos.SetXYZ(x, y, z);
  } else { // z-fixed disks
    double zscale = z / t->p4().Pz();
    double x = t->p4().Px() * zscale;
    double y = t->p4().Py() * zscale;
    hitpos.SetXYZ(x, y, z);
  }
  t->setStopVtx(hitpos);
}

//-----------------------------------------------------------------------

TMatrixD PndFastSim::fRho(5, 5);
TMatrixD PndFastSim::fEta(5, 5);

ClassImp(PndFastSim)

