	out->cd();
	n_etac_4c->Write();
	n_etac_vtx->Write();
	n_etac_vtx_2->Write();
	n_events->Write();
	h_etac_nocut->Write();
	h_etac_pid->Write();
	h_etac_vtx->Write();
	h_etac_vtx_2->Write();
	h_etac_4c->Write();
