#include "PndPidCandidate.h"
#include "PndPidCorrPar.h"

#include "DetectorInfoHelper.h"
#include "CalorimeterInfoHelper.h"

/**
 * @brief Test GetInfo() from PndPidCalorimeterInfo.
 */
TEST_F(DetectorInfoTest, CalorimeterGetInfo)
{
  CalorimeterInfoHelper *detector_info = new CalorimeterInfoHelper();

  // Get a barrel track from event 8
  PndTrack *track = SetupTrack_Event(8); // end of track at (39.35, 8.62, 22.46)
  ASSERT_NE(track, nullptr);

  // Setup PndPidEmcInfo
  FairRuntimeDb *db = run->GetRuntimeDb();
  db->getContainer("PndPidCorrPar");
  db->getContainer("PndEmcGeoPar");
  db->getContainer("PndEmcErrorMatrixPar");
  db->initContainers(run->getRunId());

  detector_info->SetGeoPar(db);
  detector_info->SetErrorMatrixPar(db);
  detector_info->SetIdeal(kFALSE);
  detector_info->SetDetectorMode(2);
  detector_info->SetUsePropagator(kTRUE);
  PndGeanePro *propagator = new PndGeanePro();
  detector_info->SetPropagator(propagator);
  detector_info->SetupErrorMatrix();
  detector_info->SetCalibrator();
  detector_info->ActivateDebugNtuple(kFALSE);
  detector_info->SetPidHypo(-211);
  detector_info->SetCorrPar(dynamic_cast<PndPidCorrPar *>(db->getContainer("PndPidCorrPar")));

  // Create cluster in EMC far away from track
  detector_info->SetCluster(136060002, TVector3(-50, -10, 600), kTRUE);
  detector_info->PreprocessTracks(0, track);
  // Make sure that cluster was created
  ASSERT_EQ(detector_info->GetClusterCount(), 1);
  // Create negatively charged PndPidCandidate
  PndPidCandidate *cand = new PndPidCandidate();
  cand->SetCharge(-1);
  ASSERT_EQ(cand->GetCharge(), -1);
  detector_info->ResetEmcQ(); // Set fClusterQ and fClusterList to default values

  // Run GetInfo, expect kTRUE as return if successful
  cand->SetTrackIndex(0);
  ASSERT_EQ(detector_info->GetInfo(track, cand), kTRUE);

  // PndPidCandidate should be filled with default values
  EXPECT_EQ(cand->GetEmcRawEnergy(), 0);
  EXPECT_EQ(cand->GetEmcCalEnergy(), 0);
  EXPECT_EQ(cand->GetEmcQuality(), -1);
  EXPECT_EQ(cand->GetEmcNumberOfCrystals(), 0);
  EXPECT_EQ(cand->GetEmcNumberOfBumps(), 0);
  EXPECT_EQ(cand->GetEmcModule(), -1);
  EXPECT_EQ(cand->GetEmcIndex(), -1);
  EXPECT_EQ(cand->GetEmcTimeStamp(), -1);
  EXPECT_EQ(cand->GetEmcClusterZ20(), 0);
  EXPECT_EQ(cand->GetEmcClusterZ53(), 0);
  EXPECT_EQ(cand->GetEmcClusterE1(), 0);
  EXPECT_EQ(cand->GetEmcClusterE9(), 0);
  EXPECT_EQ(cand->GetEmcClusterE25(), 0);
  EXPECT_EQ(cand->GetEmcClusterLat(), 0);

  // Create two more clusters in EMC at different positions
  detector_info->SetCluster(136060002, TVector3(50, 10, 30), kFALSE);
  detector_info->SetCluster(136060003, TVector3(10, 50, 5), kFALSE);
  detector_info->PreprocessTracks(0, track);

  // Make sure that both clusters were created
  ASSERT_EQ(detector_info->GetClusterCount(), 3);

  // Run GetInfo, expect kTRUE as return if successful
  ASSERT_EQ(detector_info->GetInfo(track, cand), kTRUE);

  // Values of PndEmcCluster are set in CalorimeterInfoHelper
  EXPECT_EQ(cand->GetEmcRawEnergy(), 25);
  EXPECT_EQ(cand->GetEmcCalEnergy(), 25);
  EXPECT_EQ((Int_t)cand->GetEmcQuality(), 5);
  EXPECT_EQ(cand->GetEmcNumberOfCrystals(), 0);
  EXPECT_EQ(cand->GetEmcNumberOfBumps(), 2);
  EXPECT_EQ(cand->GetEmcModule(), 1);
  EXPECT_EQ(cand->GetEmcIndex(), 1);
  EXPECT_EQ(cand->GetEmcTimeStamp(), 1);
  EXPECT_EQ(cand->GetEmcClusterZ20(), 0.5);
  EXPECT_EQ(cand->GetEmcClusterZ53(), 0.5);
  EXPECT_EQ(cand->GetEmcClusterE1(), 0);
  EXPECT_EQ(cand->GetEmcClusterE9(), 0);
  EXPECT_EQ(cand->GetEmcClusterE25(), 0);
  EXPECT_EQ(cand->GetEmcClusterLat(), 0.5);

  // Test GetNeutralInfo
  EXPECT_EQ(detector_info->GetClusterList()[0], kFALSE);
  EXPECT_EQ(detector_info->GetClusterList()[1], kTRUE);
  EXPECT_EQ(detector_info->GetClusterList()[2], kFALSE);

  TClonesArray *neutral_candidates = new TClonesArray("PndPidCandidate", 10);
  detector_info->GetNeutralInfo(1, neutral_candidates);
  ASSERT_EQ(neutral_candidates->GetEntriesFast(), 2);

  // ------ first entry ------
  delete cand;
  cand = nullptr;
  cand = dynamic_cast<PndPidCandidate *>(neutral_candidates->At(0));

  EXPECT_EQ(cand->GetPosition().X(), 0);
  EXPECT_EQ(cand->GetPosition().Y(), 0);
  EXPECT_EQ(cand->GetPosition().Z(), 0);
  EXPECT_EQ(cand->GetLorentzVector().T(), 25);
  EXPECT_EQ((Int_t)cand->GetLorentzVector().X(), -2);
  EXPECT_EQ((Int_t)cand->GetLorentzVector().Y(), 0);
  EXPECT_EQ((Int_t)cand->GetLorentzVector().Z(), 24);
  EXPECT_EQ(cand->GetLastHit().X(), -50);
  EXPECT_EQ(cand->GetLastHit().Y(), -10);
  EXPECT_EQ(cand->GetLastHit().Z(), 600);

  EXPECT_EQ(cand->GetEmcRawEnergy(), 25);
  EXPECT_EQ(cand->GetEmcCalEnergy(), 25);
  EXPECT_EQ((Int_t)cand->GetEmcQuality(), 298658);
  EXPECT_EQ(cand->GetEmcNumberOfCrystals(), 0);
  EXPECT_EQ(cand->GetEmcNumberOfBumps(), 2);
  EXPECT_EQ(cand->GetEmcModule(), 1);
  EXPECT_EQ(cand->GetEmcIndex(), 0);
  EXPECT_EQ(cand->GetEmcTimeStamp(), 1);
  EXPECT_EQ(cand->GetEmcClusterZ20(), 0.5);
  EXPECT_EQ(cand->GetEmcClusterZ53(), 0.5);
  EXPECT_EQ(cand->GetEmcClusterE1(), 0);
  EXPECT_EQ(cand->GetEmcClusterE9(), 0);
  EXPECT_EQ(cand->GetEmcClusterE25(), 0);
  EXPECT_EQ(cand->GetEmcClusterLat(), 0.5);

  // ------ second entry ------
  cand = dynamic_cast<PndPidCandidate *>(neutral_candidates->At(1));

  EXPECT_EQ(cand->GetPosition().X(), 0);
  EXPECT_EQ(cand->GetPosition().Y(), 0);
  EXPECT_EQ(cand->GetPosition().Z(), 0);
  EXPECT_EQ(cand->GetLorentzVector().T(), 25);
  EXPECT_EQ((Int_t)cand->GetLorentzVector().X(), 4);
  EXPECT_EQ((Int_t)cand->GetLorentzVector().Y(), 24);
  EXPECT_EQ((Int_t)cand->GetLorentzVector().Z(), 2);
  EXPECT_EQ(cand->GetLastHit().X(), 10);
  EXPECT_EQ(cand->GetLastHit().Y(), 50);
  EXPECT_EQ(cand->GetLastHit().Z(), 5);

  EXPECT_EQ(cand->GetEmcRawEnergy(), 25);
  EXPECT_EQ(cand->GetEmcCalEnergy(), 25);
  EXPECT_EQ((Int_t)cand->GetEmcQuality(), 2877);
  EXPECT_EQ(cand->GetEmcNumberOfCrystals(), 0);
  EXPECT_EQ(cand->GetEmcNumberOfBumps(), 2);
  EXPECT_EQ(cand->GetEmcModule(), 1);
  EXPECT_EQ(cand->GetEmcIndex(), 2);
  EXPECT_EQ(cand->GetEmcTimeStamp(), 1);
  EXPECT_EQ(cand->GetEmcClusterZ20(), 0.5);
  EXPECT_EQ(cand->GetEmcClusterZ53(), 0.5);
  EXPECT_EQ(cand->GetEmcClusterE1(), 0);
  EXPECT_EQ(cand->GetEmcClusterE9(), 0);
  EXPECT_EQ(cand->GetEmcClusterE25(), 0);
  EXPECT_EQ(cand->GetEmcClusterLat(), 0.5);
  std::cout << "Tests all tests run" << std::endl;
}

int main(int argc, char **argv)
{
  testing::InitGoogleTest(&argc, argv);
  return RUN_ALL_TESTS();
}

