class TGeant3;

/**
 * @class PndPidTrackInfo
 * @brief Base class for accessing PID track information.
 * @details  Through the function GetInfo() the track information is included in the PidCandidate.
 * @author Sarah Gaiser <gaiser@hiskp.uni-bonn.de>, HISKP Bonn
 * @version 1.0
 * @date Jan 2021
 */
class PndPidTrackInfo {
 public:
  /**
   * @brief Default constructor.
   */
  PndPidTrackInfo();
  virtual ~PndPidTrackInfo(); ///< Default destructor.

  void SetUsePropagator(Bool_t use_propagator) { fUsePropagator = use_propagator; };
  void SetPropagator(PndPropagator *propagator) { fPropagator = propagator; };
  void SetPidHypo(Int_t pid_hyp) { fPidHyp = pid_hyp; };
  void SetVerbose(Int_t verbose) { fVerbose = verbose; };
  void SetBackPropagate(Bool_t back_propagate) { fBackPropagate = back_propagate; };
  void SetTrackBranch(TString track_branch) { fTrackBranch = track_branch; };

  Int_t GetNTracksTotal() { return ((fTrack != nullptr) ? fTrack->GetEntriesFast() : 0);};

  virtual void Register() {};

  /**
   * @brief Set McTrack TClonesArray.
   * @param manager Needed to get MC track TCA of event.
   * @return kTRUE if TCA set successfully.
   */
  Bool_t SetMcTrack(FairRootManager *manager);

  /**
   * @brief Include track information in PidCandidate.
   * @param track_index Index of track in TCA.
   * @param pidCand PidCandidate belonging to track.
   * @return kTRUE if successful.
   */
  Bool_t GetInfo(Int_t track_index, PndPidCandidate *pidCand);

  /**
   * @brief Get number of tracks in barrel or forward detector.
   * @details Depending on the flag fIsBarrel either the number of tracks
   * in the barrel detector (kTRUE) or in the forward detector (kFALSE) is returned.
   * @return Number of tracks.
   */
  Int_t GetNTracks();

  /**
   * @brief Get track from barrel or foward track TClonesArrays.
   * @details Depending on the flag fIsBarrel either the track at "index"
   * in the barrel detector (kTRUE) or in the forward detector (kFALSE) is returned.
   * @param index Index of track in TCA.
   * @return The track at "index" in TCA.
   */
  PndTrack *GetTrack(Int_t index);

  /**
   * @brief Get track from MC track TClonesArrays.
   * @param index Index of track in TCA.
   * @return The track at "index" in TCA.
   */
  PndMCTrack *GetMcTrack(Int_t index);

  Bool_t SetTrackArrays(FairRootManager *manager);

 protected:
  Bool_t fUsePropagator = kFALSE;       ///< kTRUE to use propagator like PndGeanePro.
  PndPropagator *fPropagator = nullptr;  ///< The propagator.
  Int_t fPidHyp = 0;                    ///< Particle Id hypothesis (pdg particle code)
  Int_t fVerbose = 0;                   ///< Verbosity level.

  TString fTrackBranch = "";
  TClonesArray *fTrack = nullptr;
  TClonesArray *fMcTrack = nullptr;
  Bool_t fBackPropagate = kFALSE;
  Bool_t fIsBarrel = kTRUE;

  ClassDef(PndPidTrackInfo, 1);
};

#endif // PID_TRACK_INFO__H

