    TVector3 vtx(d[0], d[1], d[2]);

    TLorentzVector lv;
    lv.SetXYZM(d[3], d[4], d[5], 0.13957);

    // std::cout<< "pos glob "<<d[0]<<" "<<d[1]<<" "<<d[2]<<std::endl;
    //     std::cout<< "mom glob "<<d[3]<<" "<<d[4]<<" "<<d[5]<<std::endl;

