    int ii, jj;

    for (ii = 0; ii < 6; ii++)
      for (jj = 0; jj < 6; jj++)
        mat[ii][jj] = globalCov[ii][jj];

    // Extend matrix for energy (with default pion hypothesis)
    double invE = 1. / lv.E();
    //  mat[0+3][3+3] = mat[3+3][0+3] = (lv.X()*mat[0+3][0+3]+lv.Y()*mat[0+3][1+3]+lv.Z()*mat[0+3][2+3])*invE;
