TEST_F(DetectorInfoTest, DskGetInfo)
{
  DskInfoHelper *detector_info = new DskInfoHelper();

  // Get a barrel track from event 4

  PndTrack *track = SetupTrack_Event(4); // end of track at (-53.77, 2.43, 189.20)
  ASSERT_NE(track, nullptr);

  // Setup PndPidDskInfo
  FairRuntimeDb *db = run->GetRuntimeDb();
  db->getContainer("PndPidCorrPar");
  db->initContainers(run->getRunId());

  detector_info->SetIdeal(kFALSE);
  detector_info->SetDetectorMode(2);
  detector_info->SetUsePropagator(kTRUE);
  PndGeanePro *propagator = new PndGeanePro();
  detector_info->SetPropagator(propagator);
  detector_info->ActivateDebugNtuple(kFALSE);
  detector_info->SetPidHypo(-211);
  detector_info->SetCorrPar((PndPidCorrPar *)db->getContainer("PndPidCorrPar"));

  // Create DSK hit far from track
  TVector3 vec(60, -3, 600.);
  detector_info->SetDskParticle(vec, 1, kTRUE);

  // Make sure that hit was created
  ASSERT_EQ(detector_info->GetDskParticle()->GetEntriesFast(), 1);

  // Create negatively charged PndPidCandidate
  PndPidCandidate *cand = new PndPidCandidate();
  cand->SetCharge(-1);
  ASSERT_EQ(cand->GetCharge(), -1);

  // Run GetInfo, expect kTRUE as return if successful
  ASSERT_EQ(detector_info->GetInfo(track, cand), kTRUE);

  // PndPidCandidate should be filled with default values
  EXPECT_EQ(cand->GetDiscQuality(), -1);
  EXPECT_EQ(cand->GetDiscThetaC(), 0);
  EXPECT_EQ(cand->GetDiscNumberOfPhotons(), 0);
  EXPECT_EQ(cand->GetDiscIndex(), -1);

  // Create two more DSK hits at different positions
  TVector3 vec1(55, -2, 195);
  // TVector3 vec2(-53.7, 2.4, 189.2);
  TVector3 vec2(-56.17, 1.766, 198.001);

  detector_info->SetDskParticle(vec1, 1, kFALSE);
  detector_info->SetDskParticle(vec2, 1, kFALSE);

  // Make sure that both hits were created
  ASSERT_EQ(detector_info->GetDskParticle()->GetEntriesFast(), 3);

  // Run GetInfo, expect kTRUE as return if successful
  ASSERT_EQ(detector_info->GetInfo(track, cand), kTRUE);

  // Values of PndDskParticle are set in DskInfoHelper
  EXPECT_EQ((Int_t)cand->GetDiscQuality(), 0);
  EXPECT_EQ(cand->GetDiscThetaC(), 1);
  EXPECT_EQ(cand->GetDiscNumberOfPhotons(), 0);
  EXPECT_EQ(cand->GetDiscIndex(), 2);
}

