TEST_F(DetectorInfoTest, FtofGetInfo)
{
  FtofInfoHelper *detector_info = new FtofInfoHelper();

  // Get a forward track from event 27
  PndTrack *track = SetupTrack_Event(27); // end of track at (47.6, 29.41, 653.54)
  ASSERT_NE(track, nullptr);

  // Setup PndPidFtofInfo
  FairRuntimeDb *db = run->GetRuntimeDb();
  db->getContainer("PndPidCorrPar");
  db->initContainers(run->getRunId());

  detector_info->SetIdeal(kFALSE);
  detector_info->SetDetectorMode(2);
  detector_info->SetUsePropagator(kTRUE);
  PndGeanePro *propagator = new PndGeanePro();
  detector_info->SetPropagator(propagator);
  detector_info->ActivateDebugNtuple(kFALSE);
  detector_info->SetPidHypo(-11);
  detector_info->SetCorrPar((PndPidCorrPar *)db->getContainer("PndPidCorrPar"));

  // Create FTOF hit far from track
  TVector3 vec(10, -10, 20);
  detector_info->SetFtofHit(vec, 1, kTRUE);

  // Make sure that hit was created
  ASSERT_EQ(detector_info->GetFtofHit()->GetEntriesFast(), 1);

  // Create negatively charged PndPidCandidate
  PndPidCandidate *cand = new PndPidCandidate();
  cand->SetCharge(-1);
  ASSERT_EQ(cand->GetCharge(), -1);

  // Run GetInfo, expect kTRUE as return if successful
  ASSERT_EQ(detector_info->GetInfo(track, cand), kTRUE);

  // PndPidCandidate should be filled with default values
  EXPECT_EQ(cand->GetTofQuality(), -1);
  EXPECT_EQ(cand->GetTofStopTime(), 0);
  EXPECT_EQ(cand->GetTofTrackLength(), 0);
  EXPECT_EQ(cand->GetTofM2(), 0);
  EXPECT_EQ(cand->GetTofIndex(), -1);

  // Create two more FTOF hits at different positions
  TVector3 vec1(-50, -30, 655);
  TVector3 vec2(50, 30, 655); //(47.6, 29.41, 653.54)

  detector_info->SetFtofHit(vec1, 1, kFALSE);
  detector_info->SetFtofHit(vec2, 1, kFALSE);

  // Make sure that both hits were created
  ASSERT_EQ(detector_info->GetFtofHit()->GetEntriesFast(), 3);

  // Run GetInfo, expect kTRUE as return if successful
  ASSERT_EQ(detector_info->GetInfo(track, cand), kTRUE);

  // Values of PndFtofHit are set in FtofInfoHelper
  EXPECT_EQ((Int_t)cand->GetTofQuality(), 3);
  EXPECT_EQ(cand->GetTofStopTime(), 1);
  EXPECT_EQ((Int_t)cand->GetTofTrackLength(), 664);
  EXPECT_EQ((Int_t)cand->GetTofM2(), 0);
  EXPECT_EQ(cand->GetTofIndex(), 2);
}

